import openpyxl

def get_green_cells(file_path):
    wb = openpyxl.load_workbook(file_path)
    ws = wb.active
    greens = []
    green_rgbs = {"FF00FF00","FF008000","FF00FF99","FF33CC33","FF66CC00"}
    for row in ws.iter_rows():
        for cell in row:
            fill = cell.fill
            if fill and fill.fgColor and getattr(fill.fgColor, 'type', None) == 'rgb':
                if fill.fgColor.rgb in green_rgbs:
                    greens.append((cell.row, cell.column))
    return greens

